#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session path required");auto original=loadGraph(argv[1]);RecoveredOwnedDmxReferenceProjectionCandidate<Graph> projection(original,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external resolver required for this fixture");});size_t references=0;for(auto item:projection.attributeLocations){auto*bound=projection.scene.attributes.resolve(item.first);auto location=item.second;const auto&a=original.elements[location.first].attributes[location.second];if(!bound||bound->references().size()!=a.values.size())throw std::runtime_error("attribute projection");for(unsigned i=0;i<a.values.size();++i){auto expected=a.values[i].reference==0xffffffffu?0xffffffffu:projection.elementHandles.at(a.values[i].reference);if(bound->references()[i]!=expected)throw std::runtime_error("reference projection");++references;}}size_t notifications=0,removed=0;auto notify=[&](auto&,bool){++notifications;};auto before=[&](auto&){++removed;};projection.scene.cleanup(projection.elementHandles,notify,before);if(projection.scene.size()!=original.elements.size()||removed)throw std::runtime_error("all-root retention");projection.scene.cleanup({},notify,before);if(projection.scene.size()||projection.scene.attributes.size()||projection.scene.references.handles.active()||projection.scene.attributes.handles.active()||projection.scene.references.nodes.allocationCount()||removed!=original.elements.size())throw std::runtime_error("session teardown");validateGraph(projection.graph);if(projection.graph.elements.size()!=original.elements.size()||projection.graph.strings!=original.strings)throw std::runtime_error("source graph changed");for(unsigned i=0;i<original.elements.size();++i){const auto&a=original.elements[i];const auto&b=projection.graph.elements[i];if(a.id!=b.id||a.type!=b.type||a.name!=b.name||a.attributes.size()!=b.attributes.size())throw std::runtime_error("element preservation");for(unsigned j=0;j<a.attributes.size();++j){const auto&x=a.attributes[j];const auto&y=b.attributes[j];if(x.name!=y.name||x.type!=y.type||x.values.size()!=y.values.size())throw std::runtime_error("attribute preservation");for(unsigned k=0;k<x.values.size();++k){const auto&v=x.values[k];const auto&w=y.values[k];if(v.wire!=w.wire||v.text!=w.text||v.reference!=w.reference||v.stringIndex!=w.stringIndex)throw std::runtime_error("value preservation");}}}if(projection.graph.header!=original.header)throw std::runtime_error("header preservation");std::cout<<"session_elements="<<original.elements.size()<<" owned_reference_attributes="<<projection.attributeLocations.size()<<" projected_reference_values="<<references<<" collected_elements="<<removed<<" retained_full_graph=1"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
